WITH lines AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) li AS tier_value) SELECT id, effective_from, tier_value, RANK() OVER (ORDER BY tier_value NULLS LAST) AS tier_value_rank, CUME_DIST() OVER (ORDER BY tier_value NULLS FIRST) AS tier_value_cume_dist, DENSE_RANK() OVER (ORDER BY tier_value NULLS LAST) AS tier_value_dense_rank, DENSE_RANK() OVER (ORDER BY tier_value DESC) AS tier_value_dense_rank_2 FROM lines
